/**
 * Project interactable-only display tags that the presentation layer needs to
 * react to immediately on first world sync.
 * @param {any} world
 * @param {number} id
 * @param {string} kind
 * @param {EntityView} rec
 */
function projectInteractableDisplayTags(world, id, kind, rec) {
	if (String(kind || "").toLowerCase() !== "fountain") return;
	const charges = Number(world.get(id, FountainState)?.chargesRemaining);
	if (Number.isFinite(charges) && charges <= 0 && !rec.tags.includes("inactive")) {
		rec.tags.push("inactive");
	}
}

function projectTrapDisplayTags(world, id, rec) {
	const trap = world.get(id, Trap);
	if (!trap || trap.revealed !== true) return;
	const type = String(trap.type || "").toLowerCase();
	if (type && !rec.tags.includes(`trap_${type}`)) rec.tags.push(`trap_${type}`);
	if (trap.armed === true && !rec.tags.includes("trap_armed")) rec.tags.push("trap_armed");
import { defineComponent } from "../../lib/ecs-js/index.js";

/**
 * Durable gameplay state owned by a fountain entity.
 * Zero-valued fields are initialized deterministically on first interaction.
 */
export const FountainState = defineComponent("FountainState", {
  initialized: false,
  chargesRemaining: 0,
  maxCharges: 0,
  primaryEffect: "",
  cooldownTurns: 0,
  dryUntilStep: -1,
});
  near: "you hear water gushing to life",
});

/** Refill every dry fountain whose durable cooldown has elapsed. */
export function fountainRegrowthSystem(world) {
  const nowStep = Number(world.step || 0) | 0;
  const depth = currentDepth(world, 0);
  for (const [targetId, state] of world.query(FountainState)) {
    if (state.chargesRemaining > 0 || state.maxCharges <= 0) continue;
    if (state.dryUntilStep < 0 || nowStep < state.dryUntilStep) continue;

    world.set(targetId, FountainState, {
      ...state,
      chargesRemaining: state.maxCharges,
      dryUntilStep: -1,
    });
    world.emit(new FountainRefilled({
      targetId,
      chargesRemaining: state.maxCharges,
      cooldownTurns: state.cooldownTurns,
    }));

    const pos = world.get(targetId, Position);
    world.emit("ambient:sound", {
      source: "fountain",
      at: { x: Number(pos?.x || 0) | 0, y: Number(pos?.y || 0) | 0 },
      depth,
      sourceDbAt1Tile: FOUNTAIN_SOURCE_DB_AT_1_TILE,
      clarity: FOUNTAIN_CLARITY,
      targetId,
    });
  }
}

