    Number(info.swollenStacks || 0) | 0,
    wetness >= 0.55 ? 1 : 0,
  );
  const soggy = Math.max(
    Number(materialState?.soggyStacks || 0) | 0,
    Number(info.soggyStacks || 0) | 0,
    wetness >= 0.45 ? 1 : 0,
  );
  const ruinedByWater = materialState?.ruinedByWater === true || info?.ruinedByWater === true;

